INSERT OR IGNORE INTO revisions (entity, entity_key, revision, operation_id, snapshot_json, author, created_at) VALUES
  ('section', '102', 2, 'motivation-and-notation-2026-11-25', '{"tag":"7HE6","kind":"section","title":"Smoothed prime sums","intro_tex":"The zeros of $L(s,\\chi)$ are poles of its logarithmic derivative, a Dirichlet series over prime powers. The \\hyperref[8JF7]{smoothed prime sum} $G_\\chi$ turns this series into a function of $x$ whose \\hyperref[8JS2]{Mellin transform} recovers these poles, the starting point of \\ref{7HM3}.\n\n\\textbf{The von Mangoldt function.} For $\\Re s>1$, the Euler factor $L_p(s,\\chi)=(1-\\chi(p)p^{-s})^{-1}$ of the \\hyperref[8JC4]{Dirichlet $L$-function} satisfies\n\\begin{align*}\n-\\frac{L_p''}{L_p}(s,\\chi)\n  &= \\frac{\\chi(p)\\ln p\\;p^{-s}}{1-\\chi(p)p^{-s}} \\\\\n  &= \\sum_{k\\ge1}\\chi(p^k)\\ln p\\;p^{-ks}.\n\\end{align*}\nThe \\hyperref[8JUR]{von Mangoldt function} assigns weight $\\Lambda(p^k)=\\ln p$ to every $p^k$. Summing over $p$ gives $-\\frac{L''}{L}(s,\\chi)=\\sum_{n\\ge1}\\chi(n)\\Lambda(n)n^{-s}$ (\\ref{8JUS}). An order-$m$ zero gives a simple pole of residue $-m$, and a principal character gives one of residue $1$ at $s=1$. Thus the coefficients encode the zeros.\n\n\\textbf{The Chebyshev function and its Mellin transform.} The \\hyperref[8JUT]{generalized Chebyshev function} $\\Psi_\\chi(x)=\\sum_{n\\le x}\\chi(n)\\Lambda(n)$ reduces to Chebyshev''s $\\psi(x)$ for $\\chi=\\mathbf 1$. We write $\\Psi_\\chi$ for the classical $\\psi(x,\\chi)$ to reserve $\\psi$ for characters. Its \\hyperref[8JS2]{Mellin transform} is (\\ref{8JUU})\n\\[ \\int_1^\\infty \\Psi_\\chi(x)\\,x^{-s-1}\\,dx = -\\frac1s\\,\\frac{L''}{L}(s,\\chi) \\qquad (\\Re s>1). \\]\nThe continuation has poles at the zeros of $L(s,\\chi)$, as used in \\ref{7HM3}.\n\n\\textbf{Why smooth.} $\\Psi_\\chi$ jumps at prime powers, so its transform is not absolutely integrable on $\\Re s=c>1$: otherwise Mellin inversion would make $\\Psi_\\chi$ continuous. Integrating once removes the jumps. For $x\\ge1$,\n\\[ R_\\chi(x) = \\sum_{n\\ge1}\\chi(n)\\Lambda(n)\\Bigl(\\frac xn-1\\Bigr)_+ = x\\int_1^x \\Psi_\\chi(t)\\,\\frac{dt}{t^2}, \\]\nsince $\\int_n^x t^{-2}\\,dt=1/n-1/x$ for $n\\le x$. For $\\Re s>1$, reversing the order of integration gives\n\\begin{align*}\n\\int_1^\\infty R_\\chi(x)\\,x^{-s-1}\\,dx\n  &= \\frac{1}{s-1}\\int_1^\\infty \\Psi_\\chi(t)\\,t^{-s-1}\\,dt \\\\\n  &= -\\frac{L''}{L}(s,\\chi)\\,\\frac{1}{s(s-1)}.\n\\end{align*}\nThe extra factor $1/(s-1)$ gives $O(|s|^{-2})$ decay on $\\Re s=c>1$ and absolute convergence in Mellin inversion. Shifting left gives summable terms $-m\\,x^\\rho/(\\rho(\\rho-1))$ from order-$m$ nontrivial zeros $\\rho$ (the explicit formula for $\\zeta$ is in \\ref{8JTA}). The weight $(x/n-1)_+$ also arises from the arithmetic of Chapter 2 (\\ref{8JU4}).\n\n\\textbf{The main term.} For primitive $\\chi$, the residue of $-\\frac{L''}{L}(s,\\chi)\\frac{x^s}{s(s-1)}$ at $s=1$ gives the main term of \\ref{8JS3},\n\\begin{align*}\nM_{\\mathbf 1}(x) &= x\\ln x-(1+\\gamma)x, \\\\\nM_\\chi(x) &= -x\\,\\frac{L''}{L}(1,\\chi) \\qquad (\\chi\\ne\\mathbf 1).\n\\end{align*}\nThe first formula uses $-\\frac{\\zeta''}{\\zeta}(s)=\\frac1{s-1}-\\gamma+O(s-1)$. The \\hyperref[8JF7]{smoothed prime sum} $G_\\chi=R_\\chi-M_\\chi$ has Mellin transform regular at $s=1$, with poles exactly at the zeros of $L(s,\\chi)$ in $\\Re s>0$ (\\ref{8JN4}).","parent_id":100,"position":2}', 'codex', '2026-11-25 20:00:00'),
  ('section', '107', 4, 'motivation-and-notation-2026-11-25', '{"tag":"8JU4","kind":"section","title":"From theta lifts to a prime-power count","intro_tex":"Work at a scale $x$ in the interval of \\ref{8JU7}, with the data $A$, $A_0$, $T$, $q$, $d$ chosen there. This section contains the main deep step of the chapter: an upper bound for a weighted count of prime powers (\\ref{8JUA}). \\ref{8JU5} and \\ref{8JU6} turn this bound into the \\hyperref[8JK2]{interval estimate} by averaging and by choosing the parameters.\n\n\\textbf{The model.} If a nonzero integer $n$ is divisible by every prime in a set $P$, then\n\\[ \\sum_{p \\in P} \\ln p \\le \\ln |n|. \\]\nSo an upper bound for $|n|$ limits how many primes, weighted by $\\ln p$, can divide $n$. The proof of \\ref{8JUA} follows this pattern, with $n$ replaced by lattices built from a chain of $m$ theta lifts between unitary groups ($m$ is close to $\\sqrt x$, see \\ref{8JU6}). Prime powers in the classes counted below force extra divisibility at $p$ in these lattices. This gives a lower bound for their size (their slopes) that grows with the count. A Bost-type slope inequality bounds the same slopes from above, and comparing the two bounds gives \\ref{8JUA}. The theta lifts, the period identities and the slope estimates come from the Lean development; on a first reading, treat them as black boxes. Two steps are elementary and are stated separately: a \\hyperref[8JUB]{rank estimate} from linear algebra and the identity \\hyperref[8JUC]{matching the main terms}.\n\n\\textbf{Classes of primes.} As in \\ref{8JU3}, write $B = (\\Z/2\\Z)^2 \\times A$ additively; it is a quotient of $(\\Z/M\\Z)^\\times$. A prime $p \\nmid M$ has the class $F_p \\in B$ of $p \\bmod M$, and $p^i$ has the class $iF_p$. For the finitely many primes $p \\mid M$ the class is defined only up to a subgroup $I_p \\subseteq B$, the inertia group (for $p \\nmid M$ this subgroup is trivial). Let $\\Phi \\subseteq B$ be the subgroup of elements with first coordinate $0$. It has index $2$, and $f = |\\Phi| = 2|A|$. Let $\\xi_c$ be the character of $B$ that is $1$ on $\\Phi$ and $-1$ off $\\Phi$, the sign of the first coordinate.\n\n\\textbf{The count.} Fix $t \\in A$, a scale $a > 0$ and weights $w_\\alpha > 0$, one for each $\\alpha \\in \\Phi$. On the primes $p \\nmid M$, the count $S(t,a,w)$ of \\ref{8JU9} is\n\\[ 2 \\sum_{\\substack{p^i,\\ p \\nmid M \\\\ iF_p \\notin \\Phi}} \\ln p \\, \\Bigl( \\frac{a}{p^i} - w_{iF_p + ((1,1),t)} \\Bigr)_+ , \\]\nand each of the finitely many $p \\mid M$ is spread evenly over its coset $iF_p + I_p$. Only prime powers whose class lies outside $\\Phi$ count, and the factor $2$ makes up for using only half of the classes. Adding $((1,1),t)$ moves a class $g \\notin \\Phi$ into $\\Phi$, so each class $g$ gets its own weight $w_{g + ((1,1),t)}$, and changing $t$ permutes the weights among the classes. Since $(a/p^i - w)_+ = w\\bigl((a/w)/p^i - 1\\bigr)_+$, the smoothing is that of the \\hyperref[8JF7]{smoothed prime sum}, with a cut-off $a/w$ that depends on the class.\n\n\\textbf{The main term.} Writing the condition on the class with characters of $B$ turns $S(t,a,w)$ into a combination of the sums $R_\\xi$. Each $R_\\xi = G_\\xi + M_\\xi$ splits into a smoothed prime sum and the main term $M_\\xi$ of \\ref{8JS3}. By orthogonality only the trivial character and $\\xi_c$ leave main terms. The trivial character gives the average of $w_\\alpha M_{\\mathbf 1}(a/w_\\alpha)$ over $\\alpha \\in \\Phi$, and $\\xi_c$ gives $a\\,\\frac{L''}{L}(1,\\xi_c)$; together they make up $M(a,w)$ in \\ref{8JU9}. So $S - \\Re M$ is a combination of smoothed prime sums $G_\\xi$, and \\ref{8JU5} averages it.\n\n\\textbf{The bound.} The construction supplies a scale $a_t$ for each $t \\in T$ and weights $w_{u,j}$ for each level $1 \\le j \\le m$ of the chain and each $u \\in A_0$. \\ref{8JUA} bounds $S - \\Re M$, summed over $t \\in T$ and $1 \\le j \\le m$, from above by $x^{(e_D+e_L+3)\\varepsilon}\\mathcal B$ for an explicit quantity $\\mathcal B$, whose size \\ref{8JU6} estimates. Like the interval estimate itself, this is only an upper bound.","parent_id":105,"position":2}', 'codex', '2026-11-25 20:00:00'),
  ('result', '148', 1, 'motivation-and-notation-2026-11-25', '{"tag":"8JUR","type":"definition","title":"von Mangoldt function","statement_tex":"For integers $n\\ge1$, the \\emph{von Mangoldt function} is\n\\[ \\Lambda(n) = \\begin{cases}\n\\ln p, & n = p^k \\text{ for a prime } p \\text{ and an integer } k\\ge1, \\\\\n0, & \\text{otherwise}.\n\\end{cases} \\]","section_id":102,"position":1,"listed":1,"aliases":["von-mangoldt-function"]}', 'codex', '2026-11-25 20:00:00'),
  ('result', '149', 1, 'motivation-and-notation-2026-11-25', '{"tag":"8JUS","type":"lemma","title":"Logarithmic derivative of $L(s,\\chi)$","statement_tex":"Let $\\chi$ be a \\hyperref[8JA9]{Dirichlet character} and $\\Lambda$ the \\hyperref[8JUR]{von Mangoldt function}. For every $s\\in\\C$ with $\\Re s>1$,\n\\[ -\\frac{L''}{L}(s,\\chi) = \\sum_{n\\ge1}\\frac{\\chi(n)\\Lambda(n)}{n^s}, \\]\nand the series converges absolutely.","section_id":102,"position":2,"listed":1,"aliases":["log-derivative-l-function"]}', 'codex', '2026-11-25 20:00:00'),
  ('result', '150', 1, 'motivation-and-notation-2026-11-25', '{"tag":"8JUT","type":"definition","title":"Generalized Chebyshev function","statement_tex":"Let $\\chi$ be a \\hyperref[8JA9]{Dirichlet character}. The \\emph{generalized Chebyshev function} of $\\chi$ is\n\\[ \\Psi_\\chi(x) = \\sum_{n\\le x}\\chi(n)\\Lambda(n) \\qquad (x\\ge1), \\]\nwhere $\\Lambda$ is the \\hyperref[8JUR]{von Mangoldt function}.","section_id":102,"position":3,"listed":1,"aliases":["chebyshev-function"]}', 'codex', '2026-11-25 20:00:00'),
  ('result', '151', 1, 'motivation-and-notation-2026-11-25', '{"tag":"8JUU","type":"lemma","title":"Mellin transform of the Chebyshev function","statement_tex":"Let $\\chi$ be a \\hyperref[8JA9]{Dirichlet character} and $\\Psi_\\chi$ its \\hyperref[8JUT]{generalized Chebyshev function}. For every $s\\in\\C$ with $\\Re s>1$,\n\\[ \\int_1^\\infty \\Psi_\\chi(x)\\,x^{-s-1}\\,dx = -\\frac1s\\,\\frac{L''}{L}(s,\\chi). \\]","section_id":102,"position":4,"listed":1,"aliases":["chebyshev-mellin-transform"]}', 'codex', '2026-11-25 20:00:00'),
  ('result', '106', 3, 'motivation-and-notation-2026-11-25', '{"tag":"8JF7","type":"definition","title":"Smoothed prime sum","statement_tex":"Let $\\Lambda$ be the \\hyperref[8JUR]{von Mangoldt function} and $\\gamma$ Euler''s constant. For a \\hyperref[8JH4]{primitive character} $\\chi$ and real $x \\ge 1$ put\n\\[ R_\\chi(x) = \\sum_{n \\ge 1} \\chi(n)\\Lambda(n)\\Bigl(\\frac{x}{n} - 1\\Bigr)_+, \\qquad v_+ = \\max(v, 0), \\]\nand\n\\[ G_\\chi(x) = \\begin{cases} R_{\\mathbf 1}(x) - x\\ln x + (1+\\gamma)x, & \\chi = \\mathbf 1, \\\\[4pt] R_\\chi(x) + x\\,\\dfrac{L''(1,\\chi)}{L(1,\\chi)}, & \\chi \\ne \\mathbf 1. \\end{cases} \\]\nHere \\hyperref[8JUV]{$L(1,\\chi) \\ne 0$} for $\\chi \\ne \\mathbf 1$.","section_id":102,"position":5,"listed":1,"aliases":["smoothed-prime-sum"]}', 'codex', '2026-11-25 20:00:00'),
  ('result', '116', 6, 'motivation-and-notation-2026-11-25', '{"tag":"8JS3","type":"lemma","title":"Growth of the smoothed prime sums","statement_tex":"Let $\\chi$ be a \\hyperref[8JH4]{primitive character}, let $R_\\chi$ and $G_\\chi$ be as in the \\hyperref[8JF7]{definition of the smoothed prime sum}, let\n\\[ M_\\chi(x) = R_\\chi(x) - G_\\chi(x) = \\begin{cases} x\\ln x - (1+\\gamma)x, & \\chi = \\mathbf 1, \\\\[4pt] -x\\,\\dfrac{L''(1,\\chi)}{L(1,\\chi)}, & \\chi \\ne \\mathbf 1, \\end{cases} \\]\nbe the main term, and let $c_{\\mathbf 1} = 1+\\gamma$ and $c_\\chi = \\bigl|L''(1,\\chi)/L(1,\\chi)\\bigr|$ for $\\chi \\ne \\mathbf 1$.\n\\begin{enumerate}\n\\item[(i)]  $|R_\\chi(x)| \\le x\\ln x\\,(1+\\ln x)$ for $x \\ge 1$.\n\\item[(ii)] $|M_\\chi(x)| \\le c_\\chi\\, x\\,(1+\\ln x)$ for $x \\ge 1$.\n\\item[(iii)] $|G_\\chi(x)| \\le (1+c_\\chi)\\, x\\,(1+\\ln x)^2$ for $x \\ge 1$. \\\\\nIn particular $G_\\chi(x) = O_\\varepsilon(x^{1+\\varepsilon})$ for every $\\varepsilon > 0$.\n\\end{enumerate}\nSee the \\hyperref[8JS9]{example} of the trivial character.","section_id":102,"position":6,"listed":1,"aliases":["smoothed-sum-growth"]}', 'codex', '2026-11-25 20:00:00'),
  ('result', '107', 2, 'motivation-and-notation-2026-11-25', '{"tag":"8JG8","type":"definition","title":"Cyclic family and weighted sum","statement_tex":"Let $\\psi$ be a \\hyperref[8JH4]{primitive character} of \\hyperref[8JA9]{order} $o$, and let\n\\[ \\mathcal C_\\psi = \\left\\{ (\\psi^j)^* \\;\\middle|\\; j \\in \\Z,\\ 0 \\le j < o \\right\\} \\]\nbe the set of primitive characters \\hyperref[8JB2]{inducing} its powers. It contains $\\mathbf 1$ and $\\psi$ and is closed under $\\chi \\mapsto \\bar\\chi$. With the weights\n\\[ a_{\\mathbf 1} = 1, \\qquad a_\\chi = \\frac{1}{3o+1} \\quad (\\chi \\ne \\mathbf 1), \\]\nset\n\\[ \\mathcal G_\\psi(x) = \\sum_{\\chi \\in \\mathcal C_\\psi} a_\\chi \\Re G_\\chi(x) \\qquad (x \\ge 1), \\]\nwhere $G_\\chi$ is the \\hyperref[8JF7]{smoothed prime sum}. This one real function \\hyperref[8JM7]{sees the zeros of every $L(s,\\chi)$ with $\\chi \\in \\mathcal C_\\psi$}; in \\hyperref[7HM3]{the deduction} only the positivity of the weights matters. See the \\hyperref[8JJ5]{example} of the character modulo $4$.","section_id":102,"position":7,"listed":1,"aliases":["weighted-sum"]}', 'codex', '2026-11-25 20:00:00'),
  ('result', '108', 1, 'motivation-and-notation-2026-11-25', '{"tag":"8JJ5","type":"example","title":"The character modulo $4$","statement_tex":"Let $\\psi = \\chi_{-4}$ be the \\hyperref[8JA9]{Dirichlet character} modulo $4$ given by\n\\[ \\chi_{-4}(n) = \\begin{cases} 1, & n \\equiv 1 \\pmod 4, \\\\ -1, & n \\equiv 3 \\pmod 4, \\\\ 0, & n \\text{ even}. \\end{cases} \\]\nIt is \\hyperref[8JH4]{primitive} of order $o = 2$. Its powers are $\\psi^0 = \\chi_0$, the \\hyperref[8JE3]{principal character} modulo $4$, which is \\hyperref[8JB2]{induced} by $\\mathbf 1$, and $\\psi^1 = \\chi_{-4}$ itself. So the \\hyperref[8JG8]{cyclic family} and its weights are\n\\[ \\mathcal C_{\\chi_{-4}} = \\{\\mathbf 1, \\chi_{-4}\\}, \\qquad a_{\\mathbf 1} = 1, \\qquad a_{\\chi_{-4}} = \\frac{1}{3 \\cdot 2 + 1} = \\frac17. \\]\nBoth characters are real-valued, so $L(s,\\chi)$ has real coefficients, $L(1,\\chi)$ and $L''(1,\\chi)$ are real, and each $G_\\chi(x)$ is already real; the weighted sum is therefore simply\n\\[ \\mathcal G_{\\chi_{-4}}(x) = G_{\\mathbf 1}(x) + \\tfrac17\\, G_{\\chi_{-4}}(x). \\]\nWhich zeros it detects is worked out in the \\hyperref[8JQ3]{continued example}.","section_id":102,"position":8,"listed":0,"aliases":["example-mod-4"]}', 'codex', '2026-11-25 20:00:00'),
  ('result', '109', 1, 'motivation-and-notation-2026-11-25', '{"tag":"8JQ3","type":"example","title":"The character modulo $4$, continued","statement_tex":"Continue the \\hyperref[8JJ5]{example} $\\psi = \\chi_{-4}$, with $\\mathcal C_{\\chi_{-4}} = \\{\\mathbf 1, \\chi_{-4}\\}$ and weights $1, \\frac17$. Write\n\\[ \\beta(s) = L(s, \\chi_{-4}) = 1 - 3^{-s} + 5^{-s} - 7^{-s} + \\cdots \\]\nfor the Dirichlet beta function, and $m_\\zeta(\\rho)$, $m_\\beta(\\rho)$ for the multiplicities of $\\rho$ as a zero of $\\zeta$ and $\\beta$. Both characters are real, so $m_{\\bar\\chi} = m_\\chi$ and the \\hyperref[8JM7]{general remark} gives\n\\[ S_\\rho = m_\\zeta(\\rho) + \\tfrac17\\, m_\\beta(\\rho). \\]\nSo the Mellin transform of $G_{\\mathbf 1} + \\frac17 G_{\\chi_{-4}}$ has a pole at every zero $\\rho$ of $\\zeta$ or of $\\beta$ in $\\Re s > 0$, with residue\n\\[ -\\frac{m_\\zeta(\\rho) + \\frac17\\, m_\\beta(\\rho)}{\\rho(\\rho - 1)}. \\]\nA common zero of $\\zeta$ and $\\beta$ gives a single pole whose residue adds both contributions. Thus one bound on $\\mathcal G_{\\chi_{-4}}$ controls the zeros of $\\zeta$ and of $\\beta$ together.","section_id":102,"position":9,"listed":0,"aliases":["example-mod-4-zeros"]}', 'codex', '2026-11-25 20:00:00'),
  ('result', '152', 1, 'motivation-and-notation-2026-11-25', '{"tag":"8JUV","type":"lemma","title":"Non-vanishing of $L(1,\\chi)$","statement_tex":"Let $\\chi \\ne \\mathbf 1$ be a \\hyperref[8JH4]{primitive character}. Then $L(1,\\chi)\\ne0$.","section_id":102,"position":10,"listed":0,"aliases":["l-at-one-nonzero"]}', 'codex', '2026-11-25 20:00:00'),
  ('result', '119', 4, 'motivation-and-notation-2026-11-25', '{"tag":"8JS6","type":"example","title":"Mellin transforms of the smoothed prime sums","statement_tex":"Let $\\chi$ and $\\psi$ be \\hyperref[8JH4]{primitive characters}, let $\\mathcal C_\\psi$, $a_\\chi$ and $\\mathcal G_\\psi$ be as in the \\hyperref[8JG8]{definition of the cyclic family}, and let $b_\\chi = L''(1,\\chi)/L(1,\\chi)$ for $\\chi \\ne \\mathbf 1$. The \\hyperref[8JS2]{Mellin transforms}\n\\[ H_\\chi = \\mathcal M G_\\chi, \\qquad \\mathcal H_\\psi = \\mathcal M \\mathcal G_\\psi \\]\nof the \\hyperref[8JF7]{smoothed prime sum} and of the \\hyperref[8JG8]{weighted sum} are \\hyperref[8JS3]{defined for $\\Re s > 1$}, and there:\n\\begin{enumerate}\n\\item[(i)] \\begin{align*}\nH_\\chi(s) &= -\\frac{L''}{L}(s,\\chi)\\frac{1}{s(s-1)} + \\frac{b_\\chi}{s-1} && (\\chi \\ne \\mathbf 1), \\\\\nH_{\\mathbf 1}(s) &= -\\frac{\\zeta''}{\\zeta}(s)\\frac{1}{s(s-1)} - \\frac{1}{(s-1)^2} + \\frac{1+\\gamma}{s-1}.\n\\end{align*}\n\\item[(ii)] \\[ \\mathcal H_\\psi(s) = \\frac12 \\sum_{\\chi \\in \\mathcal C_\\psi} a_\\chi \\bigl(H_\\chi(s) + H_{\\bar\\chi}(s)\\bigr). \\]\n\\end{enumerate}","section_id":104,"position":2,"listed":1,"aliases":["mellin-smoothed-sum"]}', 'codex', '2026-11-25 20:00:00'),
  ('result', '128', 2, 'motivation-and-notation-2026-11-25', '{"tag":"8JU9","type":"definition","title":"The weighted prime-power count","statement_tex":"For each prime $p$ let $I_p\\subseteq B$ be its inertia group and $F_p$ a representative of its Frobenius coset. For $t\\in A$ and $g\\notin\\Phi$ set $p_t(g)=g+((1,1),t)\\in\\Phi$. For real $a>0$ and weights $w=(w_\\alpha)_{\\alpha\\in\\Phi}$ with $w_\\alpha>0$, set\n$$\nS(t,a,w)=\\sum_{p,\\ i\\ge 1}\\sum_{g\\notin\\Phi}\n\\frac{2\\mathbf 1_{g-iF_p\\in I_p}}{|I_p|}\\ln p\\,\n\\left(\\frac{a}{p^i}-w_{p_t(g)}\\right)_+.\n$$\nHere $v_+=\\max(v,0)$ for real $v$. Write $\\xi_c$ for the sign character of the first coordinate, using its primitive representative in $L(s,\\xi_c)$, and set\n$$\nM(a,w)=a\\left(\\ln a-1-\\gamma+\\frac{L''}{L}(1,\\xi_c)\n-\\frac1f\\sum_{\\alpha\\in\\Phi}\\ln w_\\alpha\\right).\n$$","section_id":107,"position":1,"listed":1,"aliases":[]}', 'codex', '2026-11-25 20:00:00'),
  ('result', '131', 2, 'motivation-and-notation-2026-11-25', '{"tag":"8JUC","type":"lemma","title":"Matching the main terms","statement_tex":"In the normalization of \\cite[Section 8]{Outline}, write $A_* =\\sum_t a_t$, $\\ell=\\Re(L''/L)(1,\\xi_c)$, and let $v_0$ be the geometric normalization parameter. The divisibility main term is\n$$\nD_{\\rm div}=m\\sum_t a_t(\\ln a_t-1-\\gamma-\\ln(\\pi/v_0)+\\ell).\n$$\nThe threshold is $\\lambda=\\sum_j f^{-1}\\sum_{\\alpha\\in\\Phi}\\ln(w_{j,\\alpha}v_0/\\pi)+mg_0-E_{\\rm count}$, where $g_0$ is the common logarithmic index term and $E_{\\rm count}$ the error in the counting lower bound. Then\n$$\nD_{\\rm div}-A_*\\lambda+mA_*g_0\n=\\sum_{t,j}\\Re M(a_t,w_j)+A_*E_{\\rm count}.\n$$","section_id":107,"position":4,"listed":0,"aliases":[]}', 'codex', '2026-11-25 20:00:00'),
  ('result', '141', 6, 'motivation-and-notation-2026-11-25', '{"tag":"8JTA","type":"example","title":"The Riemann zeta function","statement_tex":"Take $\\psi = \\mathbf 1$, the \\hyperref[8JH4]{trivial character}, so that $L(s, \\mathbf 1) = \\zeta(s)$ and $o = 1$. The \\hyperref[8JG8]{cyclic family} is $\\mathcal C_{\\mathbf 1} = \\{\\mathbf 1\\}$ with weight $a_{\\mathbf 1} = 1$, so the weighted sum is the \\hyperref[8JF7]{smoothed prime sum} of the \\hyperref[8JS9]{trivial character}:\n\\[ \\mathcal G_{\\mathbf 1}(x) = G_{\\mathbf 1}(x) = \\sum_{n \\le x} \\Lambda(n)\\Bigl(\\frac xn - 1\\Bigr) - x\\ln x + (1+\\gamma)x. \\]\n\n\\emph{Poles.} By \\ref{8JS6} and \\ref{8JN4}, the Mellin transform\n\\[ H_{\\mathbf 1}(s) = -\\frac{\\zeta''}{\\zeta}(s)\\,\\frac{1}{s(s-1)} - \\frac{1}{(s-1)^2} + \\frac{1+\\gamma}{s-1} \\]\nhas a simple pole at each nontrivial zero $\\rho$ of $\\zeta$, with residue $-m(\\rho)/(\\rho(\\rho-1))$, where $m(\\rho)$ is the multiplicity. Moreover, \\hyperref[8JUH]{none of these poles is real}. So for $\\zeta$ only case (a) in the proof of the \\hyperref[8JT5]{lower bound} can occur.\n\n\\emph{Explicit formula.} The \\hyperref[8JUK]{residue theorem} gives, for $x \\ge 1$,\n\\[ G_{\\mathbf 1}(x) = \\ln 2\\pi - \\sum_\\rho \\frac{x^\\rho}{\\rho(\\rho - 1)} - \\sum_{n \\ge 1} \\frac{x^{-2n}}{2n(2n+1)}, \\]\nwhere $\\rho$ runs over the nontrivial zeros of $\\zeta$, counted with multiplicity. Each zero $\\rho = \\beta + i\\gamma$ contributes an oscillation $x^\\rho = x^\\beta e^{i\\gamma\\ln x}$ of size $x^\\beta$.\n\n\\emph{Taylor coefficients.} Since $\\int_1^\\infty x^\\rho\\, x^{-s-1}\\,dx = \\frac{1}{s - \\rho}$ for $\\Re s > \\Re\\rho$, the \\hyperref[8JS2]{Mellin transform} of the explicit formula is\n\\begin{align*}\nH_{\\mathbf 1}(s) = \\frac{\\ln 2\\pi}{s} &- \\sum_\\rho \\frac{1}{\\rho(\\rho-1)(s - \\rho)} \\\\\n&- \\sum_{n \\ge 1} \\frac{1}{2n(2n+1)(s + 2n)}.\n\\end{align*}\nHence, for $\\Re z > 1$ and $k \\ge 0$, the coefficients $A_k(z) = \\frac{(-1)^k}{k!}H_{\\mathbf 1}^{(k)}(z)$ are\n\\begin{align*}\nA_k(z) = \\frac{\\ln 2\\pi}{z^{k+1}} &- \\sum_\\rho \\frac{1}{\\rho(\\rho-1)(z - \\rho)^{k+1}} \\\\\n&- \\sum_{n \\ge 1} \\frac{1}{2n(2n+1)(z + 2n)^{k+1}}.\n\\end{align*}\nEach pole $p$ of $H_{\\mathbf 1}$, with residue $c$, contributes $c/(z - p)^{k+1}$, so for large $k$ the poles nearest to $z$ dominate. The \\hyperref[8JUP]{one-sided bound} uses the integral for $A_k$, and the \\hyperref[8JUM]{lower bound} uses this series directly.\n\n\\emph{What the theorem says here.} For $\\psi = \\mathbf 1$ the \\hyperref[8JK2]{interval estimate} only asks that $G_{\\mathbf 1}(x) \\le x^{1/2 + 9\\varepsilon}$ on sparse intervals $[Y, Y^{3/2}]$. The \\hyperref[8JUQ]{zeta interval criterion}, applied with $\\theta=1/2+9\\varepsilon$ for every sufficiently small $\\varepsilon>0$, rules out nontrivial zeros to the right of the critical line. The functional equation then gives the Riemann hypothesis. Conversely, if the Riemann hypothesis holds, then $|x^\\rho| = \\sqrt x$ and $\\rho(1 - \\rho) = |\\rho|^2$ for every zero, and $\\sum_\\rho \\frac{1}{\\rho(1-\\rho)} = 2 + \\gamma - \\ln 4\\pi \\approx 0.0462$ \\cite{Davenport}. With $\\sum_{n \\ge 1} \\frac{1}{2n(2n+1)} = 1 - \\ln 2 < 0.307$, the explicit formula then gives the much stronger two-sided bound\n\\[ |G_{\\mathbf 1}(x) - \\ln 2\\pi| \\le 0.0462\\sqrt x + 0.307 \\qquad (x \\ge 1). \\]\n\n\\emph{Graphs.} Panel (a) shows $G_{\\mathbf 1}(x)$ for $1 \\le x \\le 10^7$, on a logarithmic $x$-axis, with this bound dashed.\n\\begin{center}\n\\textbf{(a)} $G_{\\mathbf 1}(x)$ and the bound $\\ln 2\\pi \\pm (0.0462\\sqrt x + 0.307)$, for $1 \\le x \\le 10^7$\n\\end{center}\n\\includegraphics[width=1, alt=G_1(x) for x from 1 to 10 million on a logarithmic axis, oscillating with amplitude up to about 45, well inside the dashed curves ln 2 pi plus or minus (0.0462 sqrt x + 0.307)]{/static/figures/zeta-smoothed-sum.svg}\nPanel (b) shows $(G_{\\mathbf 1}(x) - \\ln 2\\pi)/\\sqrt x$ for $10 \\le x \\le 10^7$, together with the explicit formula cut off after the first zero pair $\\frac12 \\pm 14.1347\\,i$, which is a pure wave in $\\ln x$, and after the first ten zero pairs, which already follows the data closely.\n\\begin{center}\n\\textbf{(b)} $\\bigl(G_{\\mathbf 1}(x) - \\ln 2\\pi\\bigr)/\\sqrt x$ and the explicit formula with the first one and ten zero pairs, for $10 \\le x \\le 10^7$\n\\end{center}\n\\includegraphics[width=1, alt=The normalized smoothed sum oscillating with size about 0.01 to 0.02, the first zero pair giving a pure wave and the first ten zero pairs following the data closely]{/static/figures/zeta-oscillation.svg}\nPanel (c) shows $|A_k(\\frac32 + i\\tau)|$ for $k = 0, 1, 2, 3$ and $0 \\le \\tau \\le 50$, on a logarithmic scale; the dotted lines mark the heights $\\gamma$ of the zeros $\\frac12 + i\\gamma$. Here $\\sigma - \\frac12 = 1$, so at $\\tau = \\gamma$ the zero $\\rho = \\frac12 + i\\gamma$ contributes a term of size $1/|\\rho|^2$ for every $k$, while the terms of the farther poles shrink as $k$ grows. For $k = 0$ and $1$ the pole at $s = 0$, with its comparatively large residue $\\ln 2\\pi \\approx 1.84$, still dominates, and the zeros only make small dents. From $k = 2$ on, peaks of height about $1/|\\rho|^2$ appear at the zeros. A zero $\\beta + i\\gamma$ with $\\beta > \\frac12$ would instead give peaks growing like $(\\frac32 - \\beta)^{-k}$, which is what the \\hyperref[8JT5]{lower bound} detects.\n\\begin{center}\n\\textbf{(c)} $|A_k(\\frac32 + i\\tau)|$ for $k = 0, 1, 2, 3$ and $0 \\le \\tau \\le 50$; dotted lines at the zero heights $\\gamma$\n\\end{center}\n\\includegraphics[width=1, alt=The absolute values of A_0 to A_3 on the line Re s = 3/2 for tau from 0 to 50 on a logarithmic scale, with peaks at the heights of the zeros of zeta appearing from k = 2 on]{/static/figures/zeta-taylor-coefficients.svg}","section_id":110,"position":2,"listed":1,"aliases":["zeta-example"]}', 'codex', '2026-11-25 20:00:00'),
  ('proof', '101', 6, 'motivation-and-notation-2026-11-25', '{"result_id":111,"position":1,"body_tex":"\\emph{(i)} The right-hand sides in \\ref{8JS6}(i) are meromorphic on $\\C$. At $s = 1$ the singular parts cancel: for $\\chi \\ne \\mathbf 1$ because $-\\frac{L''}{L}(1,\\chi) = -b_\\chi$, and for $\\chi = \\mathbf 1$ because $-\\frac{\\zeta''}{\\zeta}(s) = \\frac{1}{s-1} - \\gamma + O(s-1)$ gives\n\\[ -\\frac{\\zeta''}{\\zeta}(s)\\,\\frac{1}{s(s-1)} = \\frac{1}{(s-1)^2} - \\frac{1+\\gamma}{s-1} + O(1). \\]\nAt a zero $\\rho$ of $L(s,\\chi)$ with $\\Re\\rho > 0$ (so $\\rho \\ne 0, 1$), $-\\frac{L''}{L}(s,\\chi)$ has a simple pole with residue $-m_\\chi(\\rho)$, which gives the stated residue.\n\n\\emph{(ii)} By (i) and \\ref{8JS6}(ii), $\\mathcal H_\\psi$ extends meromorphically to $\\Re s > 0$, its poles are simple and lie in $Z$, and at $\\rho \\in Z$\n\\[ \\operatorname{Res}_{s=\\rho} \\mathcal H_\\psi = \\frac12 \\sum_{\\chi \\in \\mathcal C_\\psi} a_\\chi\\, \\frac{-m_\\chi(\\rho) - m_{\\bar\\chi}(\\rho)}{\\rho(\\rho-1)} = -\\frac{S_\\rho}{\\rho(\\rho-1)}, \\]\nwhich is nonzero because \\hyperref[8JS5]{$S_\\rho > 0$}.","status":"ai_generated","generated_by":"claude","generator_detail":"claude-opus-5-5","reviewed_by":null,"review_notes":null}', 'codex', '2026-11-25 20:00:00'),
  ('proof', '106', 5, 'motivation-and-notation-2026-11-25', '{"result_id":119,"position":1,"body_tex":"\\emph{(i)} Since\n\\[ \\int_n^\\infty \\Bigl(\\frac xn - 1\\Bigr) x^{-s-1}\\,dx = \\frac{n^{-s}}{s(s-1)} \\]\nand the series of the \\hyperref[8JUS]{logarithmic derivative} converges absolutely, we may integrate term by term:\n\\[ \\int_1^\\infty R_\\chi(x)\\, x^{-s-1}\\,dx = \\frac{1}{s(s-1)} \\sum_{n \\ge 1} \\Lambda(n)\\chi(n)\\, n^{-s} = -\\frac{L''}{L}(s,\\chi)\\,\\frac{1}{s(s-1)}. \\]\nThe remaining terms come from $\\int_1^\\infty x \\cdot x^{-s-1}\\,dx = \\frac1{s-1}$ and $\\int_1^\\infty x\\ln x \\cdot x^{-s-1}\\,dx = \\frac1{(s-1)^2}$.\n\n\\emph{(ii)} Since \\hyperref[8JS5]{$\\overline{L(\\bar s,\\chi)} = L(s,\\bar\\chi)$}, we have $\\overline{G_\\chi} = G_{\\bar\\chi}$, so $\\Re G_\\chi = \\frac12(G_\\chi + G_{\\bar\\chi})$. Now use the linearity of $\\mathcal M$.","status":"ai_generated","generated_by":"claude","generator_detail":"claude-opus-5-5","reviewed_by":null,"review_notes":null}', 'codex', '2026-11-25 20:00:00'),
  ('proof', '117', 2, 'motivation-and-notation-2026-11-25', '{"result_id":132,"position":1,"body_tex":"\\emph{Idea.} Expand the local count in characters, use the large weights to read off the sum at scale $x$, and average in two stages.\n\n\\emph{(1)} \\textbf{Inertia averaging gives the Fourier expansion at every prime.} For a character $\\xi$ of $B$ set $c_\\xi(p^i)=|I_p|^{-1}\\sum_{v\\in I_p}\\xi(iF_p+v)$. For $g\\in B$, orthogonality gives\n$$\n\\frac1f\\sum_{\\xi\\in\\widehat B}\\overline{\\xi(g)}c_\\xi(p^i)\n=\\frac2{|I_p|}\\mathbf 1_{g-iF_p\\in I_p}.\n$$\nHere $2=|B|/f$. Substituting this in \\ref{8JU9} and using $(a/p^i-w)_+=w((a/w)/p^i-1)_+$ gives $wG_\\xi(a/w)$ together with the main term $M(a,w)$. The trivial character contributes the logarithmic term. The sign character equals $-1$ off $\\Phi$ and gives the term $a(L''/L)(1,\\xi_c)$.\n\n\\emph{(2)} \\textbf{Averaging over $A_0$ leaves a coefficient $\\delta_2/2$.} The $h_2$ large weights are indexed by a subset of $A_0$. Replace them by $b$, discard the small weights, and later return to $x$ using $|a_t/b-x|\\le 1$. The \\hyperref[8JUE]{weight estimates} control these replacements. For a large-weight index $z\\in A_0$, the Fourier factors depending on $u,z$ are $\\xi(-u)\\xi(-z)$, where $A$ is embedded in $B$. Their average over $u\\in A_0$ vanishes unless $\\xi|_{A_0}=1$. In that case the factor in $z$ is also $1$, giving $b h_2/f=b\\delta_2/2$ at each level and translate.\n\n\\emph{(3)} \\textbf{The coset distribution retains the powers of $\\psi$ with their prescribed weights.} On $A/A_0$ the target distribution is $\\lambda_\\alpha=(3+\\mathbf 1_{\\alpha\\in A_0})/(3o+1)$. Its Fourier coefficient at the trivial character is $1$. For any nontrivial character, the constant part sums to zero and the atom at the identity contributes $1/(3o+1)$. Thus the retained terms have exactly the coefficients of $\\mathcal G_\\psi$ in \\ref{8JG8}. The error from the coset proportions and the return to $x$ is bounded in \\cite[Sections 13--14]{Outline} by $4x^{1/2+\\varepsilon}$ at the normalized scale. The sum $\\Sigma(x)$ of \\ref{8JUW} has at most $4o$ terms, and the joint choice of $q,d$ bounds each term by $x^{1/2+\\varepsilon}$. Averaging the upper bound for $\\Delta_u$ now gives the two inequalities.","status":"ai_generated","generated_by":"gpt","generator_detail":"Codex","reviewed_by":null,"review_notes":null}', 'codex', '2026-11-25 20:00:00'),
  ('proof', '124', 1, 'motivation-and-notation-2026-11-25', '{"result_id":144,"position":1,"body_tex":"\\emph{The unnormalized sum $R_{\\mathbf 1}(x)$.} Apply the \\hyperref[8JUJ]{integral for the positive part} with $y=x/n$, multiply by $\\Lambda(n)$, and sum. Absolute convergence of $\\sum_n \\Lambda(n)n^{-s}=-\\zeta''(s)/\\zeta(s)$ on $\\Re s=2$ allows the interchange, giving\n\\[\nR_{\\mathbf 1}(x)=\\frac{1}{2\\pi i}\\int_{2-i\\infty}^{2+i\\infty} I_x(s)\\,ds,\n\\qquad I_x(s)=-\\frac{\\zeta''(s)}{\\zeta(s)}\\frac{x^s}{s(s-1)}.\n\\]\n\nShift the contour to the left. The residue theorem separates the four contributions to $R_{\\mathbf 1}(x)$.\n\\begin{alignat*}{2}\ns=1 &\\quad x\\ln x-(1+\\gamma)x\n&\\qquad& \\text{main term},\\\\\ns=0 &\\quad \\ln 2\\pi\n&& \\text{constant term},\\\\\ns=\\rho &\\quad -\\frac{m(\\rho)x^\\rho}{\\rho(\\rho-1)}\n&& \\text{nontrivial zero of order }m(\\rho),\\\\\ns=-2n &\\quad -\\frac{x^{-2n}}{2n(2n+1)}\n&& \\text{simple trivial zero }(n\\ge 1).\n\\end{alignat*}\n\nAt $1$ the pole of $\\zeta$ gives $-\\zeta''/\\zeta(s)=1/(s-1)-\\gamma+O(s-1)$. The factor $1/(s-1)$ in the kernel makes this a double pole. Using $x^s/s=x+x(\\ln x-1)(s-1)+O_x((s-1)^2)$ gives the main term in the first row. At $0$ the kernel has residue $-1$, so the contribution is $\\zeta''(0)/\\zeta(0)=\\ln 2\\pi$. At a zero of order $m$, the residue of $-\\zeta''/\\zeta$ is $-m$.\n\nFor the contour shift, fix a positive odd integer $R$ and take the horizontal sides at heights $\\pm T$ along a sequence with $\\zeta''/\\zeta=O_R((\\ln T)^2)$ for $-R\\le\\Re s\\le 2$ \\cite{Davenport}. Their integrals tend to zero as $T\\to\\infty$ because the kernel is $O_{x,R}(T^{-2})$ there. On $\\Re s=-R$, logarithmic differentiation of the functional equation gives $\\zeta''/\\zeta(s)=O(\\ln(R+|t|+2))$ uniformly in $R$ and $t=\\operatorname{Im}s$. Indeed, the cotangent term is bounded on these lines, the gamma term is $O(\\ln(R+|t|+2))$, and $\\zeta''/\\zeta(1-s)$ is bounded by its Dirichlet series. The integral on the left line is therefore $O(x^{-R}\\ln(R+2)/R)$, which tends to zero as $R\\to\\infty$ even at $x=1$. The zero count $N(T)=O(T\\ln T)$ gives absolute convergence of the nontrivial-zero sum for each $x\\ge 1$. The trivial-zero sum converges by comparison with $\\sum n^{-2}$.\n\n\\emph{The normalized sum $G_{\\mathbf 1}(x)$.} Subtract the residue at $1$ from $R_{\\mathbf 1}(x)$, as in the \\hyperref[8JF7]{definition of $G_{\\mathbf 1}$}. The residue at $0$ gives the constant offset, a conjugate pair of nontrivial zeros gives an oscillation in $\\ln x$, and the trivial zeros contribute terms that decay as $x\\to\\infty$.","status":"ai_generated","generated_by":"gpt","generator_detail":"Codex","reviewed_by":null,"review_notes":null}', 'codex', '2026-11-25 20:00:00'),
  ('proof', '128', 1, 'motivation-and-notation-2026-11-25', '{"result_id":149,"position":1,"body_tex":"Take logarithmic derivatives of the Euler factors, using local uniform convergence of the product on $\\Re s>1$, and expand by geometric series to obtain\n\\begin{align*}\n-\\frac{L''}{L}(s,\\chi)\n  &= \\sum_p \\frac{\\chi(p)\\ln p\\;p^{-s}}{1-\\chi(p)p^{-s}} \\\\\n  &= \\sum_p\\sum_{k\\ge1}\\chi(p^k)\\ln p\\;p^{-ks}\n   = \\sum_{n\\ge1}\\frac{\\chi(n)\\Lambda(n)}{n^s}.\n\\end{align*}\nAbsolute convergence follows from $\\Lambda(n)\\le\\ln n$.","status":"ai_generated","generated_by":"gpt","generator_detail":"Codex","reviewed_by":null,"review_notes":null}', 'codex', '2026-11-25 20:00:00'),
  ('proof', '129', 1, 'motivation-and-notation-2026-11-25', '{"result_id":151,"position":1,"body_tex":"By absolute convergence of the \\hyperref[8JUS]{logarithmic derivative series}, we may integrate $\\Psi_\\chi(x)=\\sum_n\\chi(n)\\Lambda(n)\\mathbf 1_{n\\le x}$ term by term. Using $\\int_n^\\infty x^{-s-1}\\,dx=n^{-s}/s$ and \\ref{8JUS} gives\n\\[ \\int_1^\\infty \\Psi_\\chi(x)\\,x^{-s-1}\\,dx = \\frac1s\\sum_{n\\ge1}\\frac{\\chi(n)\\Lambda(n)}{n^s} = -\\frac1s\\,\\frac{L''}{L}(s,\\chi). \\]","status":"ai_generated","generated_by":"gpt","generator_detail":"Codex","reviewed_by":null,"review_notes":null}', 'codex', '2026-11-25 20:00:00');

UPDATE sections SET intro_tex = 'As explained in \ref{8JV3}, the \hyperref[8JF7]{smoothed prime sum} $G_\chi$ turns the Dirichlet series for the logarithmic derivative into a function of $x$ whose \hyperref[8JS2]{Mellin transform} recovers the poles at zeros of $L(s,\chi)$, the starting point of \ref{7HM3}.', intro_html_cache = NULL, revision = revision + 1, updated_at = '2026-11-25 20:00:00', updated_by = 'codex' WHERE id = 102;

UPDATE sections SET intro_tex = 'Work at a scale $x$ in the interval of \ref{8JU7}, with the data $A$, $A_0$, $T$, $q$, $d$ chosen there. This section contains the main deep step of the chapter: an upper bound for a weighted count of prime powers (\ref{8JUA}). \ref{8JU5} and \ref{8JU6} turn this bound into the \hyperref[8JK2]{interval estimate} by averaging and by choosing the parameters.

\textbf{The model.} If a nonzero integer $n$ is divisible by every prime in a set $P$, then
\[ \sum_{p \in P} \ln p \le \ln |n|. \]
So an upper bound for $|n|$ limits how many primes, weighted by $\ln p$, can divide $n$. The proof of \ref{8JUA} follows this pattern, with $n$ replaced by lattices built from a chain of $m$ theta lifts between unitary groups ($m$ is close to $\sqrt x$, see \ref{8JU6}). Prime powers in the classes counted below force extra divisibility at $p$ in these lattices. This gives a lower bound for their size (their slopes) that grows with the count. A Bost-type slope inequality bounds the same slopes from above, and comparing the two bounds gives \ref{8JUA}. The theta lifts, the period identities and the slope estimates come from the Lean development; on a first reading, treat them as black boxes. Two steps are elementary and are stated separately: a \hyperref[8JUB]{rank estimate} from linear algebra and the identity \hyperref[8JUC]{matching the main terms}.

\textbf{Classes of primes.} As in \ref{8JU3}, write $B = (\Z/2\Z)^2 \times A$ additively; it is a quotient of $(\Z/M\Z)^\times$. A prime $p \nmid M$ has the class $F_p \in B$ of $p \bmod M$, and $p^i$ has the class $iF_p$. For the finitely many primes $p \mid M$ the class is defined only up to a subgroup $I_p \subseteq B$, the inertia group (for $p \nmid M$ this subgroup is trivial). Let $\Phi \subseteq B$ be the subgroup of elements with first coordinate $0$. It has index $2$, and $f = |\Phi| = 2|A|$. Let $\xi_c$ be the character of $B$ that is $1$ on $\Phi$ and $-1$ off $\Phi$, the sign of the first coordinate.

\textbf{The count.} Fix $t \in A$, a scale $a > 0$ and weights $w_\alpha > 0$, one for each $\alpha \in \Phi$. On the primes $p \nmid M$, the count $S(t,a,w)$ of \ref{8JU9} is
\[ 2 \sum_{\substack{p^i,\ p \nmid M \\ iF_p \notin \Phi}} \ln p \, \Bigl( \frac{a}{p^i} - w_{iF_p + ((1,1),t)} \Bigr)_+ , \]
and each of the finitely many $p \mid M$ is spread evenly over its coset $iF_p + I_p$. Only prime powers whose class lies outside $\Phi$ count, and the factor $2$ makes up for using only half of the classes. Adding $((1,1),t)$ moves a class $g \notin \Phi$ into $\Phi$, so each class $g$ gets its own weight $w_{g + ((1,1),t)}$, and changing $t$ permutes the weights among the classes. Since $(a/p^i - w)_+ = w\bigl((a/w)/p^i - 1\bigr)_+$, the smoothing is that of the \hyperref[8JF7]{smoothed prime sum}, with a cut-off $a/w$ that depends on the class.

\textbf{The main term.} Writing the condition on the class with characters of $B$ turns $S(t,a,w)$ into a combination of the sums $R_\xi$. Each $R_\xi = G_\xi + M_\xi$ splits into a smoothed prime sum and the main term $M_\xi$ of \ref{8JS3}. By orthogonality only the trivial character and $\xi_c$ leave main terms. The trivial character gives the average of $w_\alpha M_{\mathbf 1}(a/w_\alpha)$ over $\alpha \in \Phi$, and $\xi_c$ gives $a(L''(1,\xi_c)/L(1,\xi_c))$; together they make up $M(a,w)$ in \ref{8JU9}. So $S - \Re M$ is a combination of smoothed prime sums $G_\xi$, and \ref{8JU5} averages it.

\textbf{The bound.} The construction supplies a scale $a_t$ for each $t \in T$ and weights $w_{u,j}$ for each level $1 \le j \le m$ of the chain and each $u \in A_0$. \ref{8JUA} bounds $S - \Re M$, summed over $t \in T$ and $1 \le j \le m$, from above by $x^{(e_D+e_L+3)\varepsilon}\mathcal B$ for an explicit quantity $\mathcal B$, whose size \ref{8JU6} estimates. Like the interval estimate itself, this is only an upper bound.', intro_html_cache = NULL, revision = revision + 1, updated_at = '2026-11-25 20:00:00', updated_by = 'codex' WHERE id = 107;

UPDATE results SET position = 2, statement_html_cache = NULL, revision = revision + 1, updated_at = '2026-11-25 20:00:00', updated_by = 'codex' WHERE id = 148;

UPDATE results SET statement_tex = 'Let $\chi$ be a \hyperref[8JA9]{Dirichlet character} and $\Lambda$ the \hyperref[8JUR]{von Mangoldt function}. For every $s\in\C$ with $\Re s>1$,
\[ -\frac{L''(s,\chi)}{L(s,\chi)} = \sum_{n\ge1}\frac{\chi(n)\Lambda(n)}{n^s}, \]
and the series converges absolutely.', position = 3, statement_html_cache = NULL, revision = revision + 1, updated_at = '2026-11-25 20:00:00', updated_by = 'codex' WHERE id = 149;

