UPDATE results SET statement_tex = 'Let $\chi$ be a \hyperref[8JA9]{Dirichlet character} and $\Psi_\chi$ its \hyperref[8JUT]{generalized Chebyshev function}. For every $s\in\C$ with $\Re s>1$,
\[ \int_1^\infty \Psi_\chi(x)\,x^{-s-1}\,dx = -\frac1s\,\frac{L''(s,\chi)}{L(s,\chi)}. \]', position = 5, statement_html_cache = NULL, revision = revision + 1, updated_at = '2026-11-25 20:00:00', updated_by = 'codex' WHERE id = 151;

